INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100101_001", 1, 100101, 4, "vo_empress_100101_001", 1, "", "ヒヨリ", "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100101_002", 2, 100103, 4, "vo_empress_100101_002", 1, "", "ヒヨリ", "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100101_003", 3, 100103, 4, "vo_empress_100101_003", 1, "", "ヒヨリ", "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100101, "vo_empress_100101_004", 4, 100102, 4, "vo_empress_100101_004", 1, "", "ヒヨリ", "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100201_001", 5, 100203, 4, "vo_empress_100201_001", 1, "", "ユイ", "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100201_002", 6, 100203, 4, "vo_empress_100201_002", 1, "", "ユイ", "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100201_003", 7, 100203, 4, "vo_empress_100201_003", 1, "", "ユイ", "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100201, "vo_empress_100201_004", 8, 100202, 4, "vo_empress_100201_004", 1, "", "ユイ", "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100301_001", 9, 100301, 4, "vo_empress_100301_001", 1, "", "レイ", "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100301_002", 10, 100303, 4, "vo_empress_100301_002", 1, "", "レイ", "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100301_003", 11, 100303, 4, "vo_empress_100301_003", 1, "", "レイ", "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100301, "vo_empress_100301_004", 12, 100302, 4, "vo_empress_100301_004", 1, "", "レイ", "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100401_001", 13, 100401, 4, "vo_empress_100401_001", 1, "", "ミソギ", "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100401_002", 14, 100401, 4, "vo_empress_100401_002", 1, "", "ミソギ", "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100401_003", 15, 100403, 4, "vo_empress_100401_003", 1, "", "ミソギ", "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100401, "vo_empress_100401_004", 16, 100402, 4, "vo_empress_100401_004", 1, "", "ミソギ", "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100501_001", 17, 100501, 4, "vo_empress_100501_001", 1, "", "マツリ", "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100501_002", 18, 100501, 4, "vo_empress_100501_002", 1, "", "マツリ", "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100501_003", 19, 100503, 4, "vo_empress_100501_003", 1, "", "マツリ", "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100501, "vo_empress_100501_004", 20, 100502, 4, "vo_empress_100501_004", 1, "", "マツリ", "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100601_001", 21, 100603, 4, "vo_empress_100601_001", 1, "", "アカリ", "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100601_002", 22, 100601, 4, "vo_empress_100601_002", 1, "", "アカリ", "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100601_003", 23, 100603, 4, "vo_empress_100601_003", 1, "", "アカリ", "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100601, "vo_empress_100601_004", 24, 100602, 4, "vo_empress_100601_004", 1, "", "アカリ", "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100701_001", 25, 100701, 4, "vo_empress_100701_001", 1, "", "ミヤコ", "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100701_002", 26, 100702, 4, "vo_empress_100701_002", 1, "", "ミヤコ", "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100701_003", 27, 100703, 4, "vo_empress_100701_003", 1, "", "ミヤコ", "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100701, "vo_empress_100701_004", 28, 100702, 4, "vo_empress_100701_004", 1, "", "ミヤコ", "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100801_001", 29, 100801, 4, "vo_empress_100801_001", 1, "", "ユキ", "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100801_002", 30, 100801, 4, "vo_empress_100801_002", 1, "", "ユキ", "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100801_003", 31, 100801, 4, "vo_empress_100801_003", 1, "", "ユキ", "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100801, "vo_empress_100801_004", 32, 100802, 4, "vo_empress_100801_004", 1, "", "ユキ", "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100901_001", 33, 100901, 4, "vo_empress_100901_001", 1, "", "アンナ", "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_100901_002", 34, 100903, 4, "vo_empress_100901_002", 1, "", "アンナ", "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_100901_003", 35, 100903, 4, "vo_empress_100901_003", 1, "", "アンナ", "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 100901, "vo_empress_100901_004", 36, 100902, 4, "vo_empress_100901_004", 1, "", "アンナ", "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101001_001", 37, 101001, 4, "vo_empress_101001_001", 1, "", "マホ", "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101001_002", 38, 101001, 4, "vo_empress_101001_002", 1, "", "マホ", "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101001_003", 39, 101003, 4, "vo_empress_101001_003", 1, "", "マホ", "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101001, "vo_empress_101001_004", 40, 101002, 4, "vo_empress_101001_004", 1, "", "マホ", "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101101_001", 41, 101101, 4, "vo_empress_101101_001", 1, "", "リノ", "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101101_002", 42, 101101, 4, "vo_empress_101101_002", 1, "", "リノ", "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101101_003", 43, 101103, 4, "vo_empress_101101_003", 1, "", "リノ", "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101101, "vo_empress_101101_004", 44, 101102, 4, "vo_empress_101101_004", 1, "", "リノ", "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101201_001", 45, 101201, 4, "vo_empress_101201_001", 1, "", "ハツネ", "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101201_002", 46, 101202, 4, "vo_empress_101201_002", 1, "", "ハツネ", "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101201_003", 47, 101203, 4, "vo_empress_101201_003", 1, "", "ハツネ", "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101201, "vo_empress_101201_004", 48, 101202, 4, "vo_empress_101201_004", 1, "", "ハツネ", "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101301_001", 49, 101301, 4, "vo_empress_101301_001", 1, "", "ナナカ", "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101301_002", 50, 101301, 4, "vo_empress_101301_002", 1, "", "ナナカ", "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101301_003", 51, 101303, 4, "vo_empress_101301_003", 1, "", "ナナカ", "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101301, "vo_empress_101301_004", 52, 101302, 4, "vo_empress_101301_004", 1, "", "ナナカ", "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101401_001", 53, 101401, 4, "vo_empress_101401_001", 1, "", "カスミ", "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101401_002", 54, 101401, 4, "vo_empress_101401_002", 1, "", "カスミ", "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101401_003", 55, 101403, 4, "vo_empress_101401_003", 1, "", "カスミ", "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101401, "vo_empress_101401_004", 56, 101402, 4, "vo_empress_101401_004", 1, "", "カスミ", "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101501_001", 57, 101501, 4, "vo_empress_101501_001", 1, "", "ミサト", "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101501_002", 58, 101501, 4, "vo_empress_101501_002", 1, "", "ミサト", "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101501_003", 59, 101501, 4, "vo_empress_101501_003", 1, "", "ミサト", "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101501, "vo_empress_101501_004", 60, 101502, 4, "vo_empress_101501_004", 1, "", "ミサト", "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101601_001", 61, 101601, 4, "vo_empress_101601_001", 1, "", "スズナ", "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101601_002", 62, 101601, 4, "vo_empress_101601_002", 1, "", "スズナ", "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101601_003", 63, 101601, 4, "vo_empress_101601_003", 1, "", "スズナ", "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101601, "vo_empress_101601_004", 64, 101602, 4, "vo_empress_101601_004", 1, "", "スズナ", "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101701_001", 65, 101701, 4, "vo_empress_101701_001", 1, "", "カオリ", "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101701_002", 66, 101701, 4, "vo_empress_101701_002", 1, "", "カオリ", "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101701_003", 67, 101703, 4, "vo_empress_101701_003", 1, "", "カオリ", "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101701, "vo_empress_101701_004", 68, 101702, 4, "vo_empress_101701_004", 1, "", "カオリ", "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101801_001", 69, 101801, 4, "vo_empress_101801_001", 1, "", "イオ", "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_101801_002", 70, 101801, 4, "vo_empress_101801_002", 1, "", "イオ", "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_101801_003", 71, 101803, 4, "vo_empress_101801_003", 1, "", "イオ", "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 101801, "vo_empress_101801_004", 72, 101802, 4, "vo_empress_101801_004", 1, "", "イオ", "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102001_001", 73, 102003, 4, "vo_empress_102001_001", 1, "", "ミミ", "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102001_002", 74, 102003, 4, "vo_empress_102001_002", 1, "", "ミミ", "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102001_003", 75, 102003, 4, "vo_empress_102001_003", 1, "", "ミミ", "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102001, "vo_empress_102001_004", 76, 102002, 4, "vo_empress_102001_004", 1, "", "ミミ", "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102101_001", 77, 102101, 4, "vo_empress_102101_001", 1, "", "クルミ", "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102101_002", 78, 102101, 4, "vo_empress_102101_002", 1, "", "クルミ", "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102101_003", 79, 102101, 4, "vo_empress_102101_003", 1, "", "クルミ", "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102101, "vo_empress_102101_004", 80, 102102, 4, "vo_empress_102101_004", 1, "", "クルミ", "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102201_001", 81, 102201, 4, "vo_empress_102201_001", 1, "", "ヨリ", "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102201_002", 82, 102201, 4, "vo_empress_102201_002", 1, "", "ヨリ", "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102201_003", 83, 102203, 4, "vo_empress_102201_003", 1, "", "ヨリ", "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102201, "vo_empress_102201_004", 84, 102202, 4, "vo_empress_102201_004", 1, "", "ヨリ", "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102301_001", 85, 102301, 4, "vo_empress_102301_001", 1, "", "アヤネ", "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102301_002", 86, 102303, 4, "vo_empress_102301_002", 1, "", "アヤネ", "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102301_003", 87, 102303, 4, "vo_empress_102301_003", 1, "", "アヤネ", "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102301, "vo_empress_102301_004", 88, 102302, 4, "vo_empress_102301_004", 1, "", "アヤネ", "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102501_001", 89, 102503, 4, "vo_empress_102501_001", 1, "", "スズメ", "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102501_002", 90, 102503, 4, "vo_empress_102501_002", 1, "", "スズメ", "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102501_003", 91, 102503, 4, "vo_empress_102501_003", 1, "", "スズメ", "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102501, "vo_empress_102501_004", 92, 102502, 4, "vo_empress_102501_004", 1, "", "スズメ", "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102601_001", 93, 102603, 4, "vo_empress_102601_001", 1, "", "リン", "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102601_002", 94, 102603, 4, "vo_empress_102601_002", 1, "", "リン", "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102601_003", 95, 102603, 4, "vo_empress_102601_003", 1, "", "リン", "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102601, "vo_empress_102601_004", 96, 102602, 4, "vo_empress_102601_004", 1, "", "リン", "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102701_001", 97, 102701, 4, "vo_empress_102701_001", 1, "", "エリコ", "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102701_002", 98, 102701, 4, "vo_empress_102701_002", 1, "", "エリコ", "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102701_003", 99, 102703, 4, "vo_empress_102701_003", 1, "", "エリコ", "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102701, "vo_empress_102701_004", 100, 102702, 4, "vo_empress_102701_004", 1, "", "エリコ", "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102801_001", 101, 102801, 4, "vo_empress_102801_001", 1, "", "サレン", "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_102801_002", 102, 102801, 4, "vo_empress_102801_002", 1, 1, "サレン", "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102801_003", 103, 102803, 4, "vo_empress_102801_003", 1, "", "サレン", "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102801, "vo_empress_102801_004", 104, 102802, 4, "vo_empress_102801_004", 1, "", "サレン", "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102901_001", 105, 102903, 4, "vo_empress_102901_001", 1, "", "ノゾミ", "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_102901_002", 106, 102903, 4, "vo_empress_102901_002", 1, "", "ノゾミ", "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_102901_003", 107, 102903, 4, "vo_empress_102901_003", 1, "", "ノゾミ", "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 102901, "vo_empress_102901_004", 108, 102901, 4, "vo_empress_102901_004", 1, "", "ノゾミ", "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103001_001", 109, 103001, 4, "vo_empress_103001_001", 1, "", "ニノン", "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103001_002", 110, 103001, 4, "vo_empress_103001_002", 1, "", "ニノン", "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103001_003", 111, 103003, 4, "vo_empress_103001_003", 1, "", "ニノン", "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103001, "vo_empress_103001_004", 112, 103002, 4, "vo_empress_103001_004", 1, "", "ニノン", "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103101_001", 113, 103101, 4, "vo_empress_103101_001", 1, "", "シノブ", "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103101_002", 114, 103101, 4, "vo_empress_103101_002", 1, "", "シノブ", "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103101_003", 115, 103103, 4, "vo_empress_103101_003", 1, "", "シノブ", "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103101, "vo_empress_103101_004", 116, 103101, 4, "vo_empress_103101_004", 1, "", "シノブ", "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103201_001", 117, 103201, 4, "vo_empress_103201_001", 1, "", "アキノ", "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103201_002", 118, 103201, 4, "vo_empress_103201_002", 1, "", "アキノ", "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103201_003", 119, 103203, 4, "vo_empress_103201_003", 1, "", "アキノ", "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103201, "vo_empress_103201_004", 120, 103202, 4, "vo_empress_103201_004", 1, "", "アキノ", "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103301_001", 121, 103301, 4, "vo_empress_103301_001", 1, "", "マヒル", "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103301_002", 122, 103301, 4, "vo_empress_103301_002", 1, "", "マヒル", "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103301_003", 123, 103303, 4, "vo_empress_103301_003", 1, "", "マヒル", "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103301, "vo_empress_103301_004", 124, 103302, 4, "vo_empress_103301_004", 1, "", "マヒル", "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103401_001", 125, 103401, 4, "vo_empress_103401_001", 1, "", "ユカリ", "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103401_002", 126, 103401, 4, "vo_empress_103401_002", 1, "", "ユカリ", "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103401_003", 127, 103403, 4, "vo_empress_103401_003", 1, "", "ユカリ", "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103401, "vo_empress_103401_004", 128, 103402, 4, "vo_empress_103401_004", 1, "", "ユカリ", "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103601_001", 129, 103603, 4, "vo_empress_103601_001", 1, "", "キョウカ", "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103601_002", 130, 103603, 4, "vo_empress_103601_002", 1, "", "キョウカ", "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103601_003", 131, 103601, 4, "vo_empress_103601_003", 1, "", "キョウカ", "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103601, "vo_empress_103601_004", 132, 103602, 4, "vo_empress_103601_004", 1, "", "キョウカ", "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103701_001", 133, 103701, 4, "vo_empress_103701_001", 1, "", "トモ", "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103701_002", 134, 103701, 4, "vo_empress_103701_002", 1, "", "トモ", "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103701_003", 135, 103701, 4, "vo_empress_103701_003", 1, "", "トモ", "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103701, "vo_empress_103701_004", 136, 103702, 4, "vo_empress_103701_004", 1, "", "トモ", "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103801_001", 137, 103801, 4, "vo_empress_103801_001", 1, "", "シオリ", "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_103801_002", 138, 103801, 4, "vo_empress_103801_002", 1, "", "シオリ", "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_103801_003", 139, 103803, 4, "vo_empress_103801_003", 1, "", "シオリ", "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 103801, "vo_empress_103801_004", 140, 103802, 4, "vo_empress_103801_004", 1, "", "シオリ", "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104001_001", 141, 104001, 4, "vo_empress_104001_001", 1, "", "アオイ", "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104001_002", 142, 104002, 4, "vo_empress_104001_002", 1, "", "アオイ", "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104001_003", 143, 104003, 4, "vo_empress_104001_003", 1, "", "アオイ", "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104001, "vo_empress_104001_004", 144, 104002, 4, "vo_empress_104001_004", 1, "", "アオイ", "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104201_001", 145, 104203, 4, "vo_empress_104201_001", 1, "", "チカ", "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104201_002", 146, 104201, 4, "vo_empress_104201_002", 1, "", "チカ", "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104201_003", 147, 104203, 4, "vo_empress_104201_003", 1, "", "チカ", "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104201, "vo_empress_104201_004", 148, 104201, 4, "vo_empress_104201_004", 1, "", "チカ", "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104301_001", 149, 104301, 4, "vo_empress_104301_001", 1, "", "マコト", "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104301_002", 150, 104301, 4, "vo_empress_104301_002", 1, "", "マコト", "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104301_003", 151, 104303, 4, "vo_empress_104301_003", 1, "", "マコト", "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104301, "vo_empress_104301_004", 152, 104302, 4, "vo_empress_104301_004", 1, "", "マコト", "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104401_001", 153, 104401, 4, "vo_empress_104401_001", 1, "", "イリヤ", "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104401_002", 154, 104401, 4, "vo_empress_104401_002", 1, "", "イリヤ", "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104401_003", 155, 104401, 4, "vo_empress_104401_003", 1, "", "イリヤ", "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104401, "vo_empress_104401_004", 156, 104401, 4, "vo_empress_104401_004", 1, "", "イリヤ", "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104501_001", 157, 104501, 4, "vo_empress_104501_001", 1, "", "クウカ", "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104501_002", 158, 104501, 4, "vo_empress_104501_002", 1, "", "クウカ", "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104501_003", 159, 104503, 4, "vo_empress_104501_003", 1, "", "クウカ", "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104501, "vo_empress_104501_004", 160, 104502, 4, "vo_empress_104501_004", 1, "", "クウカ", "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104601_001", 161, 104601, 4, "vo_empress_104601_001", 1, "", "タマキ", "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104601_002", 162, 104601, 4, "vo_empress_104601_002", 1, "", "タマキ", "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104601_003", 163, 104603, 4, "vo_empress_104601_003", 1, "", "タマキ", "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104601, "vo_empress_104601_004", 164, 104602, 4, "vo_empress_104601_004", 1, "", "タマキ", "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104701_001", 165, 104701, 4, "vo_empress_104701_001", 1, "", "ジュン", "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104701_002", 166, 104701, 4, "vo_empress_104701_002", 1, "", "ジュン", "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104701_003", 167, 104701, 4, "vo_empress_104701_003", 1, "", "ジュン", "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104701, "vo_empress_104701_004", 168, 104701, 4, "vo_empress_104701_004", 1, "", "ジュン", "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104801_001", 169, 104801, 4, "vo_empress_104801_001", 1, "", "ミフユ", "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104801_002", 170, 104801, 4, "vo_empress_104801_002", 1, "", "ミフユ", "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104801_003", 171, 104803, 4, "vo_empress_104801_003", 1, "", "ミフユ", "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104801, "vo_empress_104801_004", 172, 104802, 4, "vo_empress_104801_004", 1, "", "ミフユ", "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104901_001", 173, 104902, 4, "vo_empress_104901_001", 1, "", "シズル", "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_104901_002", 174, 104902, 4, "vo_empress_104901_002", 1, "", "シズル", "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_104901_003", 175, 104903, 4, "vo_empress_104901_003", 1, "", "シズル", "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 104901, "vo_empress_104901_004", 176, 104902, 4, "vo_empress_104901_004", 1, "", "シズル", "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105001_001", 177, 105001, 4, "vo_empress_105001_001", 1, "", "ミサキ", "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105001_002", 178, 105001, 4, "vo_empress_105001_002", 1, "", "ミサキ", "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105001_003", 179, 105003, 4, "vo_empress_105001_003", 1, "", "ミサキ", "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105001, "vo_empress_105001_004", 180, 105002, 4, "vo_empress_105001_004", 1, "", "ミサキ", "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105101_001", 181, 105101, 4, "vo_empress_105101_001", 1, "", "ミツキ", "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105101_002", 182, 105101, 4, "vo_empress_105101_002", 1, "", "ミツキ", "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105101_003", 183, 105101, 4, "vo_empress_105101_003", 1, "", "ミツキ", "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105101, "vo_empress_105101_004", 184, 105101, 4, "vo_empress_105101_004", 1, "", "ミツキ", "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105201_001", 185, 105201, 4, "vo_empress_105201_001", 1, "", "リマ", "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_105201_002", 186, 105201, 4, "vo_empress_105201_002", 1, 1, "リマ", "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105201_003", 187, 105201, 4, "vo_empress_105201_003", 1, "", "リマ", "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105201, "vo_empress_105201_004", 188, 105202, 4, "vo_empress_105201_004", 1, "", "リマ", "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105301_001", 189, 105303, 4, "vo_empress_105301_001", 1, "", "モニカ", "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105301_002", 190, 105301, 4, "vo_empress_105301_002", 1, "", "モニカ", "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105301_003", 191, 105301, 4, "vo_empress_105301_003", 1, "", "モニカ", "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105301, "vo_empress_105301_004", 192, 105302, 4, "vo_empress_105301_004", 1, "", "モニカ", "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105401_001", 193, 105401, 4, "vo_empress_105401_001", 1, "", "ツムギ", "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_105401_002", 194, 105403, 4, "vo_empress_105401_002", 1, 1, "ツムギ", "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105401_003", 195, 105403, 4, "vo_empress_105401_003", 1, "", "ツムギ", "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105401, "vo_empress_105401_004", 196, 105401, 4, "vo_empress_105401_004", 1, "", "ツムギ", "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105501_001", 197, 105503, 4, "vo_empress_105501_001", 1, "", "アユミ", "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105501_002", 198, 105501, 4, "vo_empress_105501_002", 1, "", "アユミ", "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105501_003", 199, 105503, 4, "vo_empress_105501_003", 1, "", "アユミ", "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105501, "vo_empress_105501_004", 200, 105502, 4, "vo_empress_105501_004", 1, "", "アユミ", "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105601_001", 201, 105601, 4, "vo_empress_105601_001", 1, "", "ルカ", "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105601_002", 202, 105601, 4, "vo_empress_105601_002", 1, "", "ルカ", "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105601_003", 203, 105603, 4, "vo_empress_105601_003", 1, "", "ルカ", "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105601, "vo_empress_105601_004", 204, 105602, 4, "vo_empress_105601_004", 1, "", "ルカ", "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105801_001", 205, 105803, 4, "vo_empress_105801_001", 1, "", "ペコリーヌ", "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4003, 3, 10000, 0, "vo_empress_105801_002", 206, 105801, 4, "vo_empress_105801_002", 1, 1, "ペコリーヌ", "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105801_003", 207, 105803, 4, "vo_empress_105801_003", 1, "", "ペコリーヌ", "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105801, "vo_empress_105801_004", 208, 105802, 4, "vo_empress_105801_004", 1, "", "ペコリーヌ", "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105901_001", 209, 105903, 4, "vo_empress_105901_001", 1, "", "コッコロ", "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_105901_002", 210, 105905, 4, "vo_empress_105901_002", 1, "", "コッコロ", "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_105901_003", 211, 105903, 4, "vo_empress_105901_003", 1, "", "コッコロ", "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 105901, "vo_empress_105901_004", 212, 105902, 4, "vo_empress_105901_004", 1, "", "コッコロ", "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_106001_001", 213, 106001, 4, "vo_empress_106001_001", 1, 1, "キャル", "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106001_002", 214, 106003, 4, "vo_empress_106001_002", 1, "", "キャル", "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106001_003", 215, 106003, 4, "vo_empress_106001_003", 1, "", "キャル", "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106001, "vo_empress_106001_004", 216, 106002, 4, "vo_empress_106001_004", 1, "", "キャル", "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106101_001", 217, 106102, 4, "vo_empress_106101_001", 1, "", "ノウェム", "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106101_002", 218, 106101, 4, "vo_empress_106101_002", 1, "", "ノウェム", "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106101_003", 219, 106103, 4, "vo_empress_106101_003", 1, "", "ノウェム", "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106101, "vo_empress_106101_004", 220, 106102, 4, "vo_empress_106101_004", 1, "", "ノウェム", "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106401_001", 221, 106401, 4, "vo_empress_106401_001", 1, "", "シェフィ", "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4004, 3, 10000, 0, "vo_empress_106401_002", 222, 106403, 4, "vo_empress_106401_002", 1, 1, "シェフィ", "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106401_003", 223, 106401, 4, "vo_empress_106401_003", 1, "", "シェフィ", "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106401, "vo_empress_106401_004", 224, 106402, 4, "vo_empress_106401_004", 1, "", "シェフィ", "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106501_001", 225, 106501, 4, "vo_empress_106501_001", 1, "", "カヤ", "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106501_002", 226, 106501, 4, "vo_empress_106501_002", 1, "", "カヤ", "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106501_003", 227, 106503, 4, "vo_empress_106501_003", 1, "", "カヤ", "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106501, "vo_empress_106501_004", 228, 106501, 4, "vo_empress_106501_004", 1, "", "カヤ", "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106601_001", 229, 106603, 4, "vo_empress_106601_001", 1, "", "イノリ", "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106601_002", 230, 106601, 4, "vo_empress_106601_002", 1, "", "イノリ", "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106601_003", 231, 106603, 4, "vo_empress_106601_003", 1, "", "イノリ", "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106601, "vo_empress_106601_004", 232, 106602, 4, "vo_empress_106601_004", 1, "", "イノリ", "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106701_001", 233, 106701, 4, "vo_empress_106701_001", 1, "", "ホマレ", "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106701_002", 234, 106701, 4, "vo_empress_106701_002", 1, "", "ホマレ", "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106701_003", 235, 106703, 4, "vo_empress_106701_003", 1, "", "ホマレ", "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106701, "vo_empress_106701_004", 236, 106702, 4, "vo_empress_106701_004", 1, "", "ホマレ", "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_106801_001", 237, 106802, 4, "vo_empress_106801_001", 1, "", "ラビリスタ", "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_106801_002", 238, 106801, 4, "vo_empress_106801_002", 1, 1, "ラビリスタ", "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_106801_003", 239, 106801, 4, "vo_empress_106801_003", 1, "", "ラビリスタ", "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 106801, "vo_empress_106801_004", 240, 106802, 4, "vo_empress_106801_004", 1, "", "ラビリスタ", "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_107001_001", 241, 107001, 4, "vo_empress_107001_001", 1, 1, "ネネカ", "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_107001_002", 242, 107001, 4, "vo_empress_107001_002", 1, "", "ネネカ", "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_107001_003", 243, 107001, 4, "vo_empress_107001_003", 1, "", "ネネカ", "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 107001, "vo_empress_107001_004", 244, 107002, 4, "vo_empress_107001_004", 1, "", "ネネカ", "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_107101_001", 245, 107101, 4, "vo_empress_107101_001", 1, "", "クリスティーナ", "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_107101_002", 246, 107101, 4, "vo_empress_107101_002", 1, 1, "クリスティーナ", "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_107101_003", 247, 107103, 4, "vo_empress_107101_003", 1, "", "クリスティーナ", "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 107101, "vo_empress_107101_004", 248, 107102, 4, "vo_empress_107101_004", 1, "", "クリスティーナ", "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_110801_001", 249, 110801, 4, "vo_empress_110801_001", 1, "", "クロエ", "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_110801_002", 250, 110801, 4, "vo_empress_110801_002", 1, 1, "クロエ", "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_110801_003", 251, 110803, 4, "vo_empress_110801_003", 1, "", "クロエ", "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 110801, "vo_empress_110801_004", 252, 110802, 4, "vo_empress_110801_004", 1, "", "クロエ", "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_110901_001", 253, 110901, 4, "vo_empress_110901_001", 1, "", "チエル", "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_110901_002", 254, 110901, 4, "vo_empress_110901_002", 1, "", "チエル", "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_110901_003", 255, 110903, 4, "vo_empress_110901_003", 1, "", "チエル", "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 110901, "vo_empress_110901_004", 256, 110902, 4, "vo_empress_110901_004", 1, "", "チエル", "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_111001_001", 257, 111001, 4, "vo_empress_111001_001", 1, "", "ユニ", "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_111001_002", 258, 111001, 4, "vo_empress_111001_002", 1, "", "ユニ", "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_111001_003", 259, 111003, 4, "vo_empress_111001_003", 1, "", "ユニ", "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 111001, "vo_empress_111001_004", 260, 111002, 4, "vo_empress_111001_004", 1, "", "ユニ", "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118001_001", 261, 118001, 4, "vo_empress_118001_001", 1, "", "クレジッタ", "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118001_002", 262, 118003, 4, "vo_empress_118001_002", 1, "", "クレジッタ", "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_118001_003", 263, 118003, 4, "vo_empress_118001_003", 1, "", "クレジッタ", "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 118001, "vo_empress_118001_004", 264, 118002, 4, "vo_empress_118001_004", 1, "", "クレジッタ", "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118101_001", 265, 118101, 4, "vo_empress_118101_001", 1, "", "ランファ", "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118101_002", 266, 118101, 4, "vo_empress_118101_002", 1, "", "ランファ", "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_118101_003", 267, 118103, 4, "vo_empress_118101_003", 1, "", "ランファ", "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 118101, "vo_empress_118101_004", 268, 118102, 4, "vo_empress_118101_004", 1, "", "ランファ", "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_118201_001", 269, 118201, 4, "vo_empress_118201_001", 1, 1, "ミソラ", "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118201_002", 270, 118201, 4, "vo_empress_118201_002", 1, "", "ミソラ", "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_118201_003", 271, 118202, 4, "vo_empress_118201_003", 1, "", "ミソラ", "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 118201, "vo_empress_118201_004", 272, 118202, 4, "vo_empress_118201_004", 1, "", "ミソラ", "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118501_001", 273, 118501, 4, "vo_empress_118501_001", 1, "", "カリン", "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118501_002", 274, 118502, 4, "vo_empress_118501_002", 1, "", "カリン", "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_118501_003", 275, 118503, 4, "vo_empress_118501_003", 1, "", "カリン", "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 118501, "vo_empress_118501_004", 276, 118502, 4, "vo_empress_118501_004", 1, "", "カリン", "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118601_001", 277, 118601, 4, "vo_empress_118601_001", 1, "", "ネビア", "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_118601_002", 278, 118601, 4, "vo_empress_118601_002", 1, "", "ネビア", "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_118601_003", 279, 118603, 4, "vo_empress_118601_003", 1, "", "ネビア", "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 118601, "vo_empress_118601_004", 280, 118602, 4, "vo_empress_118601_004", 1, "", "ネビア", "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_122301_001", 281, 122303, 4, "vo_empress_122301_001", 1, "", "ヴァンピィ", "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_122301_002", 282, 122302, 4, "vo_empress_122301_002", 1, "", "ヴァンピィ", "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_122301_003", 283, 122303, 4, "vo_empress_122301_003", 1, "", "ヴァンピィ", "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 122301, "vo_empress_122301_004", 284, 122302, 4, "vo_empress_122301_004", 1, "", "ヴァンピィ", "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_123001_001", 285, 123002, 4, "vo_empress_123001_001", 1, "", "アメス", "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_123001_002", 286, 123001, 4, "vo_empress_123001_002", 1, "", "アメス", "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_123001_003", 287, 123003, 4, "vo_empress_123001_003", 1, "", "アメス", "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 123001, "vo_empress_123001_004", 288, 123002, 4, "vo_empress_123001_004", 1, "", "アメス", "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_123301_001", 289, 123301, 4, "vo_empress_123301_001", 1, "", "ネア", "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_123301_002", 290, 123301, 4, "vo_empress_123301_002", 1, "", "ネア", "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_123301_003", 291, 123303, 4, "vo_empress_123301_003", 1, "", "ネア", "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 123301, "vo_empress_123301_004", 292, 123302, 4, "vo_empress_123301_004", 1, "", "ネア", "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_126401_001", 293, 126401, 4, "vo_empress_126401_001", 1, "", "クローチェ", "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_126401_002", 294, 126401, 4, "vo_empress_126401_002", 1, "", "クローチェ", "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_126401_003", 295, 126403, 4, "vo_empress_126401_003", 1, "", "クローチェ", "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 126401, "vo_empress_126401_004", 296, 126402, 4, "vo_empress_126401_004", 1, "", "クローチェ", "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_126501_001", 297, 126501, 4, "vo_empress_126501_001", 1, "", "ライラエル", "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_126501_002", 298, 126506, 4, "vo_empress_126501_002", 1, 1, "ライラエル", "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_126501_003", 299, 126503, 4, "vo_empress_126501_003", 1, "", "ライラエル", "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 126501, "vo_empress_126501_004", 300, 126502, 4, "vo_empress_126501_004", 1, "", "ライラエル", "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_127701_001", 301, 127701, 4, "vo_empress_127701_001", 1, 1, "リンド", "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_127701_002", 302, 127701, 4, "vo_empress_127701_002", 1, "", "リンド", "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_127701_003", 303, 127703, 4, "vo_empress_127701_003", 1, "", "リンド", "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 127701, "vo_empress_127701_004", 304, 127702, 4, "vo_empress_127701_004", 1, "", "リンド", "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_127801_001", 305, 127801, 4, "vo_empress_127801_001", 1, "", "ヴルム", "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_127801_002", 306, 127801, 4, "vo_empress_127801_002", 1, 1, "ヴルム", "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_127801_003", 307, 127803, 4, "vo_empress_127801_003", 1, "", "ヴルム", "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 127801, "vo_empress_127801_004", 308, 127802, 4, "vo_empress_127801_004", 1, "", "ヴルム", "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_129001_001", 309, 129001, 4, "vo_empress_129001_001", 1, 1, "エリス", "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_129001_002", 310, 129001, 4, "vo_empress_129001_002", 1, "", "エリス", "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_129001_003", 311, 129003, 4, "vo_empress_129001_003", 1, "", "エリス", "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 129001, "vo_empress_129001_004", 312, 129002, 4, "vo_empress_129001_004", 1, "", "エリス", "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_129601_001", 313, 129601, 4, "vo_empress_129601_001", 1, "", "アネモネ", "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_129601_002", 314, 129601, 4, "vo_empress_129601_002", 1, "", "アネモネ", "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_129601_003", 315, 129603, 4, "vo_empress_129601_003", 1, "", "アネモネ", "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 129601, "vo_empress_129601_004", 316, 129601, 4, "vo_empress_129601_004", 1, "", "アネモネ", "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_129701_001", 317, 129701, 4, "vo_empress_129701_001", 1, "", "ネフィ＝ネラ", "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_129701_002", 318, 129701, 4, "vo_empress_129701_002", 1, "", "ネフィ＝ネラ", "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_129701_003", 319, 129703, 4, "vo_empress_129701_003", 1, "", "ネフィ＝ネラ", "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 129701, "vo_empress_129701_004", 320, 129702, 4, "vo_empress_129701_004", 1, "", "ネフィ＝ネラ", "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4003, 3, 10000, 0, "vo_empress_130001_001", 321, 130001, 4, "vo_empress_130001_001", 1, 1, "ヤマト", "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130001_002", 322, 130001, 4, "vo_empress_130001_002", 1, "", "ヤマト", "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_130001_003", 323, 130003, 4, "vo_empress_130001_003", 1, "", "ヤマト", "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 130001, "vo_empress_130001_004", 324, 130002, 4, "vo_empress_130001_004", 1, "", "ヤマト", "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130101_001", 325, 130101, 4, "vo_empress_130101_001", 1, "", "ワカナ", "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130101_002", 326, 130101, 4, "vo_empress_130101_002", 1, "", "ワカナ", "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_130101_003", 327, 130103, 4, "vo_empress_130101_003", 1, "", "ワカナ", "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 130101, "vo_empress_130101_004", 328, 130102, 4, "vo_empress_130101_004", 1, "", "ワカナ", "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130201_001", 329, 130201, 4, "vo_empress_130201_001", 1, "", "フブキ", "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130201_002", 330, 130201, 4, "vo_empress_130201_002", 1, "", "フブキ", "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_130201_003", 331, 130203, 4, "vo_empress_130201_003", 1, "", "フブキ", "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 130201, "vo_empress_130201_004", 332, 130202, 4, "vo_empress_130201_004", 1, "", "フブキ", "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130901_001", 333, 130901, 4, "vo_empress_130901_001", 1, "", "クルル", "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_130901_002", 334, 130901, 4, "vo_empress_130901_002", 1, "", "クルル", "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_130901_003", 335, 130903, 4, "vo_empress_130901_003", 1, "", "クルル", "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 130901, "vo_empress_130901_004", 336, 130902, 4, "vo_empress_130901_004", 1, "", "クルル", "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_132301_001", 337, 132301, 4, "vo_empress_132301_001", 1, "", "ルイズマリー", "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_132301_002", 338, 132301, 4, "vo_empress_132301_002", 1, "", "ルイズマリー", "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_132301_003", 339, 132303, 4, "vo_empress_132301_003", 1, "", "ルイズマリー", "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 132301, "vo_empress_132301_004", 340, 132302, 4, "vo_empress_132301_004", 1, "", "ルイズマリー", "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_132401_001", 341, 132401, 4, "vo_empress_132401_001", 1, "", "イロハ", "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_132401_002", 342, 132401, 4, "vo_empress_132401_002", 1, "", "イロハ", "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_132401_003", 343, 132401, 4, "vo_empress_132401_003", 1, "", "イロハ", "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 132401, "vo_empress_132401_004", 344, 132402, 4, "vo_empress_132401_004", 1, "", "イロハ", "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_132501_001", 345, 132501, 4, "vo_empress_132501_001", 1, "", "ソノ", "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_132501_002", 346, 132501, 4, "vo_empress_132501_002", 1, "", "ソノ", "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_132501_003", 347, 132503, 4, "vo_empress_132501_003", 1, "", "ソノ", "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 132501, "vo_empress_132501_004", 348, 132502, 4, "vo_empress_132501_004", 1, "", "ソノ", "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_133001_001", 349, 133001, 4, "vo_empress_133001_001", 1, "", "グレイス", "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, 3, 10000, 0, "vo_empress_133001_002", 350, 133003, 4, "vo_empress_133001_002", 1, 1, "グレイス", "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_133001_003", 351, 133003, 4, "vo_empress_133001_003", 1, "", "グレイス", "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 133001, "vo_empress_133001_004", 352, 133002, 4, "vo_empress_133001_004", 1, "", "グレイス", "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_133101_001", 353, 133101, 4, "vo_empress_133101_001", 1, "", "ヴァイオレット", "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, 3, 10000, 0, "vo_empress_133101_002", 354, 133101, 4, "vo_empress_133101_002", 1, 1, "ヴァイオレット", "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_133101_003", 355, 133103, 4, "vo_empress_133101_003", 1, "", "ヴァイオレット", "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 133101, "vo_empress_133101_004", 356, 133102, 4, "vo_empress_133101_004", 1, "", "ヴァイオレット", "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_133601_001", 357, 133601, 4, "vo_empress_133601_001", 1, "", "メドゥーサ", "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_133601_002", 358, 133601, 4, "vo_empress_133601_002", 1, "", "メドゥーサ", "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_133601_003", 359, 133603, 4, "vo_empress_133601_003", 1, "", "メドゥーサ", "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 133601, "vo_empress_133601_004", 360, 133602, 4, "vo_empress_133601_004", 1, "", "メドゥーサ", "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_134701_001", 361, 134701, 4, "vo_empress_134701_001", 1, "", "ホウオウ", "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_134701_002", 362, 134701, 4, "vo_empress_134701_002", 1, "", "ホウオウ", "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_134701_003", 363, 134703, 4, "vo_empress_134701_003", 1, "", "ホウオウ", "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 134701, "vo_empress_134701_004", 364, 134702, 4, "vo_empress_134701_004", 1, "", "ホウオウ", "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_134901_001", 365, 134901, 4, "vo_empress_134901_001", 1, "", "カノン", "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_134901_002", 366, 134901, 4, "vo_empress_134901_002", 1, "", "カノン", "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_134901_003", 367, 134903, 4, "vo_empress_134901_003", 1, "", "カノン", "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 134901, "vo_empress_134901_004", 368, 134902, 4, "vo_empress_134901_004", 1, "", "カノン", "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_135501_001", 369, 135501, 4, "vo_empress_135501_001", 1, "", "アイラ", "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, 3, 10000, 0, "vo_empress_135501_002", 370, 135501, 4, "vo_empress_135501_002", 1, 1, "アイラ", "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_135501_003", 371, 135503, 4, "vo_empress_135501_003", 1, "", "アイラ", "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 135501, "vo_empress_135501_004", 372, 135502, 4, "vo_empress_135501_004", 1, "", "アイラ", "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_135601_001", 373, 135601, 4, "vo_empress_135601_001", 1, "", "シナツ", "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_135601_002", 374, 135601, 4, "vo_empress_135601_002", 1, "", "シナツ", "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_135601_003", 375, 135603, 4, "vo_empress_135601_003", 1, "", "シナツ", "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 135601, "vo_empress_135601_004", 376, 135602, 4, "vo_empress_135601_004", 1, "", "シナツ", "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, 3, 10000, 0, "vo_empress_135801_001", 377, 135801, 4, "vo_empress_135801_001", 1, 1, "ユキノ", "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_135801_002", 378, 135801, 4, "vo_empress_135801_002", 1, "", "ユキノ", "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_135801_003", 379, 135803, 4, "vo_empress_135801_003", 1, "", "ユキノ", "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 135801, "vo_empress_135801_004", 380, 135802, 4, "vo_empress_135801_004", 1, "", "ユキノ", "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, 3, 10000, 0, "vo_empress_135901_001", 381, 135903, 4, "vo_empress_135901_001", 1, 1, "サツキ", "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_135901_002", 382, 135901, 4, "vo_empress_135901_002", 1, "", "サツキ", "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_135901_003", 383, 135901, 4, "vo_empress_135901_003", 1, "", "サツキ", "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 135901, "vo_empress_135901_004", 384, 135902, 4, "vo_empress_135901_004", 1, "", "サツキ", "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_136001_001", 385, 136001, 4, "vo_empress_136001_001", 1, "", "アラクネ", "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4003, 3, 10000, 0, "vo_empress_136001_002", 386, 136001, 4, "vo_empress_136001_002", 1, 1, "アラクネ", "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_136001_003", 387, 136003, 4, "vo_empress_136001_003", 1, "", "アラクネ", "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 136001, "vo_empress_136001_004", 388, 136002, 4, "vo_empress_136001_004", 1, "", "アラクネ", "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_136201_001", 389, 136201, 4, "vo_empress_136201_001", 1, "", "ナーナ", "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_136201_002", 390, 136201, 4, "vo_empress_136201_002", 1, "", "ナーナ", "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_136201_003", 391, 136201, 4, "vo_empress_136201_003", 1, "", "ナーナ", "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 136201, "vo_empress_136201_004", 392, 136202, 4, "vo_empress_136201_004", 1, "", "ナーナ", "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, 3, 10000, 0, "vo_empress_136901_001", 393, 136903, 4, "vo_empress_136901_001", 1, 1, "ルルィ", "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_136901_002", 394, 136901, 4, "vo_empress_136901_002", 1, "", "ルルィ", "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_136901_003", 395, 136903, 4, "vo_empress_136901_003", 1, "", "ルルィ", "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 136901, "vo_empress_136901_004", 396, 136902, 4, "vo_empress_136901_004", 1, "", "ルルィ", "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_139501_001", 397, 139501, 4, "vo_empress_139501_001", 1, "", "リリ", "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_139501_002", 398, 139503, 4, "vo_empress_139501_002", 1, 1, "リリ", "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_139501_003", 399, 139503, 4, "vo_empress_139501_003", 1, "", "リリ", "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 125801, "vo_empress_139501_004", 400, 139502, 4, "vo_empress_139501_004", 1, "", "リリ", "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_139601_001", 401, 139603, 4, "vo_empress_139601_001", 1, "", "クリア", "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, 3, 10000, 0, "vo_empress_139601_002", 402, 139603, 4, "vo_empress_139601_002", 1, 1, "クリア", "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_139601_003", 403, 139603, 4, "vo_empress_139601_003", 1, "", "クリア", "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 126001, "vo_empress_139601_004", 404, 139601, 4, "vo_empress_139601_004", 1, "", "クリア", "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_139701_001", 405, 139701, 4, "vo_empress_139701_001", 1, "", "プレシア", "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, 5, "", 0, "vo_empress_139701_002", 406, 139701, 4, "vo_empress_139701_002", 1, "", "プレシア", "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, 5, "", 0, "vo_empress_139701_003", 407, 139703, 4, "vo_empress_139701_003", 1, "", "プレシア", "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 126101, "vo_empress_139701_004", 408, 139702, 4, "vo_empress_139701_004", 1, "", "プレシア", "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, 5, "", 140301, "vo_empress_140301_004", 409, 140301, 4, "vo_empress_140301_004", 1, "", "ティア", "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪");
